def for_arch(arch):
    """What a pedestrian of type `arch` (internal id) can complain about: the type's own lines plus the general ones (<= 88 letters so the speaker can say them)."""
    return [x for x in TYPE.get(arch, []) * 2 + GENERIC if len(x) <= 88] or GENERIC[:5]
